const $=id=>document.getElementById(id);
let token=sessionStorage.getItem('incident-session')||'',generation=0;
const node=(tag,text)=>{const el=document.createElement(tag);el.textContent=text;return el;};
function clear(){generation++;$('workflows').replaceChildren();$('runs').replaceChildren();$('timeline').replaceChildren();}
function state(){const signed=!!token;$('login').hidden=signed;$('logout').hidden=!signed;$('project-form').hidden=!signed;$('workspace').hidden=!signed;}
async function api(path,options={}){const response=await fetch('/api/incidents-v1'+path,{...options,headers:{...(token?{Authorization:'Bearer '+token}:{}),...(options.body?{'Content-Type':'application/json'}:{})}});const value=await response.json();if(!response.ok){if(response.status===401){token='';sessionStorage.removeItem('incident-session');clear();state();}throw Error(value.error);}return value;}
async function guard(fn){try{await fn();}catch(e){$('status').textContent=String(e.message);}}
$('login').onsubmit=e=>{e.preventDefault();guard(async()=>{const result=await api('/session',{method:'POST',body:JSON.stringify({actorId:$('actor').value,password:$('password').value})});for(const key of ['incident-project','incident-run','investigation-last','report-last','coverage-last','roi-last'])sessionStorage.removeItem(key);$('project').value='';token=result.token;sessionStorage.setItem('incident-session',token);$('password').value='';clear();state();$('status').textContent='已登录';});};
$('logout').onclick=()=>guard(async()=>{try{await api('/session',{method:'DELETE'});}finally{token='';sessionStorage.removeItem('incident-session');clear();state();$('status').textContent='已退出';}});
$('project').value=sessionStorage.getItem('incident-project')||'';
$('project').oninput=()=>{sessionStorage.removeItem('incident-run');clear();};
async function list(kind,project,epoch){let cursor='0',items=[];do{const page=await api('/'+kind+'?projectId='+encodeURIComponent(project)+'&cursor='+cursor);if(epoch!==generation)return [];items.push(...page.items);cursor=page.nextCursor;}while(cursor);return items;}
async function load(){clear();const epoch=generation,project=$('project').value;sessionStorage.setItem('incident-project',project);const [workflows,runs]=await Promise.all([list('workflows',project,epoch),list('runs',project,epoch)]);if(epoch!==generation)return;for(const w of workflows)$('workflows').append(node('p',w.workflowId+' · '+w.repoRef+' · 审批政策 '+w.approvalPolicyVersion));for(const r of runs){const button=node('button',r.taskRef+' · '+r.runId);button.onclick=()=>guard(()=>show(project,r.runId));$('runs').append(button);} $('status').textContent=`${workflows.length} 个工作流 / ${runs.length} 个运行`;}
async function show(project,id){const epoch=++generation;$('timeline').replaceChildren();const data=await api('/runs/'+encodeURIComponent(id)+'/timeline?projectId='+encodeURIComponent(project));if(epoch!==generation)return;sessionStorage.setItem('incident-run',id);const root=$('timeline');root.append(node('h2',data.run.taskRef),node('p','未采集：'+(data.missingCapture.join('；')||'无已声明缺项（不代表完整）')),node('p',data.limitations.join('\n')));for(const e of data.events){const section=document.createElement('section');section.append(node('h3',e.eventType+' · '+e.eventId),node('p',`发生 ${e.occurredAt??'未知'} / 采集 ${e.capturedAt??'未知'} / 接收 ${e.receivedAt}`),node('p',`来源 ${e.sourceId} · ${e.trust} · 序号 ${e.sourceSequence??'未知'} · 更正 ${e.supersedes??'无'}`),node('p','代码版本 '+(e.versionRefs.join(', ')||'未知')+' · 审批引用 '+(e.approvalRef??'未采集（不推断已批准）')),node('p','审批绑定：'+e.approvalCheck.status+' · '+e.approvalCheck.reasons.join(', ')),node('p','检查标记：'+(e.warnings.join(', ')||'无已发现异常（不代表已核验）')),node('p',`原件 ${e.importId} / ${e.objectId} / 行 ${e.row}`));root.append(section);}root.append(node('h3','材料及缺失项'));for(const m of data.materials)root.append(node('p',`${m.path} · ${m.status} ${m.detail??''} · ${m.importId} / ${m.objectId}`));}
$('project-form').onsubmit=e=>{e.preventDefault();guard(load);};
state();if(token)guard(async()=>{await api('/session');if($('project').value){await load();const id=sessionStorage.getItem('incident-run');if(id)await show($('project').value,id);}});



